import { useState } from 'preact/hooks';

interface Props {
    locations?: Record<string, any>;
    vehicles?: any[];
}

export const ShortBookingForm = ({ locations, vehicles }: Props) => {
    const [formData, setFormData] = useState({
        pickup: '',
        dropoff: '',
        date: '',
        passengers: '2',
        luggage: '2'
    });

    const handleSubmit = (e: Event) => {
        e.preventDefault();

        const message = `*New Booking Request* 🚖
        
📍 From: ${formData.pickup}
📍 To: ${formData.dropoff}
📅 Date: ${formData.date}
👥 Passengers: ${formData.passengers}
🧳 Luggage: ${formData.luggage}

Please confirm availability.`;

        const whatsappUrl = `https://wa.me/13073464572?text=${encodeURIComponent(message)}`;
        window.open(whatsappUrl, '_blank');
    };

    const updateField = (field: string, value: string) => {
        setFormData(prev => ({ ...prev, [field]: value }));
    };

    return (
        <div class="bg-glass p-6 rounded-xl shadow-gold max-w-md w-full mx-auto backdrop-blur-md border border-white/10">
            <h3 class="text-2xl font-bold text-white mb-2 font-heading text-center">
                VIP <span class="text-gold">Transfer Booking</span>
            </h3>
            <p class="text-xs text-gray-400 text-center mb-6">
                Serving Jeddah • Makkah • Madinah • Taif<br />
                <span class="text-red-400">* No short distance / local rides within city</span>
            </p>

            <form onSubmit={handleSubmit} class="space-y-4">
                <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {/* Pickup */}
                    <div class="form-group">
                        <label class="block text-sm text-gray-300 mb-1">Pickup Location</label>
                        <input
                            type="text"
                            required
                            placeholder="Ex: Jeddah Airport"
                            value={formData.pickup}
                            onInput={(e) => updateField('pickup', (e.target as HTMLInputElement).value)}
                            class="w-full bg-black/50 border border-gray-600 text-white rounded-lg p-3 focus:border-gold focus:outline-none transition-colors"
                        />
                    </div>

                    {/* Dropoff */}
                    <div class="form-group">
                        <label class="block text-sm text-gray-300 mb-1">Dropoff Location</label>
                        <input
                            type="text"
                            required
                            placeholder="Ex: Makkah Clock Tower"
                            value={formData.dropoff}
                            onInput={(e) => updateField('dropoff', (e.target as HTMLInputElement).value)}
                            class="w-full bg-black/50 border border-gray-600 text-white rounded-lg p-3 focus:border-gold focus:outline-none transition-colors"
                        />
                    </div>

                    {/* Date */}
                    <div class="form-group md:col-span-2">
                        <label class="block text-sm text-gray-300 mb-1">Pickup Date</label>
                        <input
                            type="date"
                            required
                            value={formData.date}
                            onInput={(e) => updateField('date', (e.target as HTMLInputElement).value)}
                            class="w-full bg-black/50 border border-gray-600 text-white rounded-lg p-3 focus:border-gold focus:outline-none transition-colors"
                        />
                    </div>

                    {/* Passengers */}
                    <div class="form-group">
                        <label class="block text-sm text-gray-300 mb-1">Passengers</label>
                        <input
                            type="number"
                            min="1"
                            max="50"
                            value={formData.passengers}
                            onInput={(e) => updateField('passengers', (e.target as HTMLInputElement).value)}
                            class="w-full bg-black/50 border border-gray-600 text-white rounded-lg p-3 focus:border-gold focus:outline-none transition-colors"
                        />
                    </div>

                    {/* Luggage */}
                    <div class="form-group">
                        <label class="block text-sm text-gray-300 mb-1">Luggage</label>
                        <input
                            type="number"
                            min="0"
                            max="50"
                            value={formData.luggage}
                            onInput={(e) => updateField('luggage', (e.target as HTMLInputElement).value)}
                            class="w-full bg-black/50 border border-gray-600 text-white rounded-lg p-3 focus:border-gold focus:outline-none transition-colors"
                        />
                    </div>
                </div>

                <button
                    type="submit"
                    class="w-full btn btn-primary text-lg mt-4 cursor-pointer flex items-center justify-center gap-2"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="currentColor" class="text-white">
                        <path d="M.057 24l1.687-6.163c-1.041-1.804-1.588-3.849-1.587-5.946.003-6.556 5.338-11.891 11.893-11.891 3.181.001 6.167 1.24 8.413 3.488 2.245 2.248 3.481 5.236 3.48 8.414-.003 6.557-5.338 11.892-11.893 11.892-1.99-.001-3.951-.5-5.688-1.448l-6.305 1.654zm6.597-3.807c1.676.995 3.276 1.591 5.392 1.592 5.448 0 9.886-4.434 9.889-9.885.002-5.462-4.415-9.89-9.881-9.892-5.452 0-9.887 4.434-9.889 9.884-.001 2.225.651 3.891 1.746 5.634l-.999 3.648 3.742-.981zm11.387-5.464c-.074-.124-.272-.198-.57-.347-.297-.149-1.758-.868-2.031-.967-.272-.099-.47-.149-.669.149-.198.297-.768.967-.941 1.165-.173.198-.347.223-.644.074-.297-.149-1.255-.462-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.297-.347.446-.521.151-.172.2-.296.3-.495.099-.198.05-.372-.025-.521-.075-.148-.669-1.611-.916-2.206-.242-.579-.487-.501-.669-.51l-.57-.01c-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.463 1.065 2.876 1.213 3.074.149.198 2.095 3.2 5.076 4.487.709.306 1.263.489 1.694.626.712.226 1.36.194 1.872.118.571-.085 1.758-.719 2.006-1.413.248-.695.248-1.29.173-1.414z" />
                    </svg>
                    Book on WhatsApp
                </button>
            </form>
        </div>
    );
};
